<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php'; require_once __DIR__ . '/../config/app.php';
if ($_SERVER['REQUEST_METHOD'] !== 'POST') { header('Location: ../index.php'); exit; } verify_csrf();
$connection=db();$items=cart_items($connection);$name=trim((string)($_POST['customer_name']??''));$phone=trim((string)($_POST['phone']??''));$email=filter_input(INPUT_POST,'email',FILTER_VALIDATE_EMAIL)?:null;$alt=trim((string)($_POST['alternative_phone']??''));
$delivery=in_array($_POST['delivery_method']??'', ['pickup','delivery'],true)?$_POST['delivery_method']:'pickup';$method=in_array($_POST['payment_method']??'', ['cash','mobile_money','bank_transfer'],true)?$_POST['payment_method']:'cash';$currency=($_POST['payment_currency']??'USD')==='SSP'?'SSP':'USD';$area=trim((string)($_POST['delivery_area']??''));$address=trim((string)($_POST['delivery_address']??''));$notes=substr(trim((string)($_POST['notes']??'')),0,1000);$reference=substr(trim((string)($_POST['reference_number']??'')),0,100);
if(!$items||$name===''||!valid_phone($phone)||($alt!==''&&!valid_phone($alt))||($delivery==='delivery'&&($area===''||$address===''))){flash('error','Please provide valid contact details and a delivery location when delivery is selected.');header('Location: ../checkout.php');exit;}
$proof=null;if(!empty($_FILES['proof']['name'])){$types=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','application/pdf'=>'pdf'];$mime=mime_content_type($_FILES['proof']['tmp_name']);if($_FILES['proof']['error']!==UPLOAD_ERR_OK||$_FILES['proof']['size']>5*1024*1024||!isset($types[$mime])){flash('error','Payment proof must be a JPG, PNG, WEBP or PDF under 5 MB.');header('Location: ../checkout.php');exit;}$proof=bin2hex(random_bytes(16)).'.'.$types[$mime];if(!move_uploaded_file($_FILES['proof']['tmp_name'],PRIVATE_STORAGE_PATH.'\\payment_proofs\\'.$proof)){flash('error','Payment proof could not be saved.');header('Location: ../checkout.php');exit;}}
$subtotal=cart_total($connection);$charge=0.0;$total=$subtotal;$paymentAmount=$currency==='SSP'?round($total*SSP_PER_USD,2):$total;$rate=$currency==='SSP'?SSP_PER_USD:null;$connection->begin_transaction();try{$statement=$connection->prepare('INSERT INTO customers (full_name, phone, email, alternative_phone) VALUES (?, ?, ?, ?) ON DUPLICATE KEY UPDATE full_name=VALUES(full_name),email=VALUES(email),alternative_phone=VALUES(alternative_phone)');$statement->bind_param('ssss',$name,$phone,$email,$alt);$statement->execute();$statement=$connection->prepare('SELECT id FROM customers WHERE phone=?');$statement->bind_param('s',$phone);$statement->execute();$customer=$statement->get_result()->fetch_assoc();$number=order_number();$statement=$connection->prepare("INSERT INTO orders (order_number, customer_id, customer_name, phone, alternative_phone, email, delivery_method, delivery_area, delivery_address, payment_method, payment_status, status, subtotal, delivery_charge, total_amount, notes) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'pending', 'new', ?, ?, ?, ?)");$statement->bind_param('sissssssssddds',$number,$customer['id'],$name,$phone,$alt,$email,$delivery,$area,$address,$method,$subtotal,$charge,$total,$notes);$statement->execute();$orderId=$connection->insert_id;foreach($items as $item){$statement=$connection->prepare('INSERT INTO order_items (order_id,product_id,product_name,quantity,unit_price) VALUES (?,?,?,?,?)');$statement->bind_param('iisid',$orderId,$item['id'],$item['name'],$item['quantity'],$item['price']);$statement->execute();}$statement=$connection->prepare('INSERT INTO payments (order_id,payment_method,amount,currency,exchange_rate,reference_number,proof_path) VALUES (?,?,?,?,?,?,?)');$statement->bind_param('isdsdss',$orderId,$method,$paymentAmount,$currency,$rate,$reference,$proof);$statement->execute();$connection->commit();$_SESSION['cart']=[];$_SESSION['new_order']=$number;header('Location: ../track.php');}catch(Throwable $exception){$connection->rollback();error_log('Sammy Tech checkout: '.$exception->getMessage());flash('error','We could not save the order. Please try again.');header('Location: ../checkout.php');}exit;
